pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 amount, address player) public {
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.assume(player != address(0) && player != address(this) && player != address(c));

        // open the game and set the bet limit to the fuzzed amount
        c.OpenToThePublic();
        c.AdjustBetAmounts(amount);

        // a real player (msg.sender == tx.origin) stakes exactly the configured limit
        vm.deal(player, amount);
        vm.prank(player);
        bool ok;
        try c.wager{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.hasPlayerWagered(player));
    }
}

