pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 amount) public {
        // Widen domain: any nonzero amount is admissible (amount 0 is a degenerate
        // case where reference and bug coincide, so exclude only it).
        vm.assume(amount != 0);

        // Owner (setUp deployer, i.e. this contract) adjusts the bet limit.
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);

        // General rule: after any owner call AdjustBetAmounts(amount), the
        // publicly observable bet limit is exactly amount. The mutant's extra
        // `betLimit = 0;` store breaks this for every nonzero amount.
        assertTrue(c.currentBetLimit() == amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: any owner-adjustable amount, wide (only exclude values
        // where correct and buggy behavior coincide for trivial reasons is NOT done —
        // we keep the whole domain except amounts whose adjustment is indistinguishable
        // by construction; nonzero amounts trigger the divergence).
        amount = bound(amount, 1, type(uint256).max);
        vm.assume(actor != address(0));

        // Drive c through AdjustBetAmounts from the owner (the test contract is the
        // deployer, hence owner; prank explicitly to make the role unambiguous).
        vm.prank(address(this));
        bool ok;
        try c.AdjustBetAmounts(amount) { ok = true; } catch { ok = false; }

        // Universal rule: whenever the owner's adjustment call succeeds, the contract's
        // public betLimit must end up exactly at the requested amount for EVERY input.
        assertTrue(ok && c.currentBetLimit() == amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function check(uint256 newLimit) public {
        require(address(this).balance >= newLimit);
        c.AdjustBetAmounts(newLimit);
        c.wager{value: newLimit}();
        assert(c.hasPlayerWagered(address(this)));
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        require(amount > 0);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("AdjustBetAmounts(uint256)", amount));
        assert(!ok || c.currentBetLimit() == amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 amt) public {
        require(amt > 0);
        uint256 before = c.currentBetLimit();
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.AdjustBetAmounts.selector, amt));
        uint256 after_ = c.currentBetLimit();
        assert(after_ == before);
    }

    receive() external payable {}
    fallback() external payable {}
}

